from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[r[:] for r in grid]; seen=set()
    for i in range(h):
      for j in range(w):
        if grid[i][j]!=bg or (i,j) in seen: continue
        q=deque([(i,j)]); seen.add((i,j)); comp=[]; edge=False
        while q:
          r,c=q.popleft(); comp.append((r,c))
          if r==0 or c==0 or r==h-1 or c==w-1: edge=True
          for a,b in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==bg and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
        if not edge:
          fill=7 if len(comp)%2 else 2
          for r,c in comp: out[r][c]=fill
    return out

